import {
  createReporter,
  getTrackedFiles,
  readFile,
  formatOffenderList,
} from "./governance-common.mjs";

const reporter = createReporter("No scan-generated AGENTS validator");
const generatedMarker = "<!-- GENERATED BY scripts/generate-repository-intelligence.mjs";
const rootAgents = readFile("AGENTS.md");
const trackedFiles = getTrackedFiles();
const activeFiles = trackedFiles.filter((file) => !file.startsWith("docs/archive/"));

reporter.assert(
  !rootAgents.startsWith(generatedMarker),
  "Root AGENTS.md must not be generated by repository intelligence scans",
);

reporter.assert(
  rootAgents.includes("HAND-AUTHORED LAW. NOT GENERATED."),
  "Root AGENTS.md must identify itself as hand-authored AGENTS_V2 law",
);

const generatedActiveFiles = activeFiles.filter((file) => {
  if (!file.endsWith("AGENTS.md") && !file.endsWith("README.md") && !file.endsWith("master-system-intelligence.md")) {
    return false;
  }
  return readFile(file).startsWith(generatedMarker);
});

reporter.assert(
  generatedActiveFiles.length === 0,
  `Active authority/docs must not be scan-generated: ${formatOffenderList(generatedActiveFiles, 10)}`,
);

const frozenManifestOnlyOffenders = activeFiles.filter((file) => {
  if (!file.endsWith("AGENTS.md")) return false;
  return readFile(file).includes("Reserved and frozen roots must stay manifest-only");
});

reporter.assert(
  frozenManifestOnlyOffenders.length === 0,
  `Active AGENTS.md files must distinguish reserved manifest-only roots from frozen source-kept roots: ${frozenManifestOnlyOffenders.join(", ")}`,
);

reporter.finish("active AGENTS and generated documentation are hand-authored or archived");
